@@ -45,1 +45,0 @@
-#include "procMapsParser.hpp"
@@ -4102,44 +4101,18 @@
-// Linux 6.8 (and the backported 6.7.6) map MAP_STACK to VM_NOHUGEPAGE. See the commit below:
-//   c4608d1bf7c6 ("mm: mmap: map MAP_STACK to VM_NOHUGEPAGE")
-//   Reference: https://github.com/torvalds/linux/commit/c4608d1bf7c6536d1a3d233eb21e50678681564e
-// glibc creates pthread stacks with MAP_STACK, so on these kernels khugepaged will not collapse
-// them into huge pages, making the THPStackMitigation redundant. Considering that the change might
-// be backported to older kernels, we use one probe to detect it at startup: map one page with
-// MAP_STACK and check the "nh" VmFlag of its VMA in /proc/self/smaps.
-static bool kernel_maps_map_stack_to_nohugepage() {
-  size_t size = os::vm_page_size();
-  void* addr = ::mmap(nullptr, size, PROT_NONE, MAP_PRIVATE|MAP_ANONYMOUS|MAP_STACK, -1, 0);
-  if (addr == MAP_FAILED) {
-    log_info(pagesize)("MAP_STACK probe: mmap failed (%s).", os::strerror(errno));
-    return false;
-  }
-  bool has_nh = false;
-  bool found = false;
-  FILE* f = os::fopen("/proc/self/smaps", "r");
-  if (f == nullptr) {
-    log_info(pagesize)("MAP_STACK probe: cannot open /proc/self/smaps.");
-  } else {
-    ProcSmapsParser parser(f);
-    ProcSmapsInfo info;
-    uintptr_t start = reinterpret_cast<uintptr_t>(addr);
-    uintptr_t end = start + size;
-    uintptr_t from, to;
-    while (parser.parse_next(info)) {
-      from = reinterpret_cast<uintptr_t>(info.from);
-      to = reinterpret_cast<uintptr_t>(info.to);
-      if (from == start && to == end) {
-        found = true;
-        has_nh = info.nh;
-        break;
-      }
-      if (from > start) {
-        break;
-      }
-    }
-    ::fclose(f);
-    if (!found) {
-      log_info(pagesize)("MAP_STACK probe: cannot find the mapping from /proc/self/smaps.");
-    }
-  }
-  ::munmap(addr, size);
-  return has_nh;
+// Returns true if the OS already prevents THPs from being allocated for stack area, which makes the
+// THPStackMitigation redundant. This requires both of the following:
+// - Linux kernel >= 6.7.6. Since this kernel version, MAP_STACK is mapped to VM_NOHUGEPAGE.
+//   See commit c4608d1bf7c6 "mm: mmap: map MAP_STACK to VM_NOHUGEPAGE".
+//   https://github.com/torvalds/linux/commit/c4608d1bf7c6536d1a3d233eb21e50678681564e
+//   https://www.kernel.org/pub/linux/kernel/v6.x/ChangeLog-6.7.6
+// - glibc >= 2.9, which creates thread stacks with MAP_STACK.
+//   musl and older glibc do not pass MAP_STACK, so it returns false.
+static bool os_prevents_thp_in_stack() {
+#ifndef __GLIBC__
+  return false; // musl
+#elif __GLIBC_PREREQ(2, 9)
+  long major, minor, patch;
+  os::Linux::kernel_version(&major, &minor, &patch);
+  return os::Linux::kernel_version_compare(major, minor, patch, 6, 7, 6) >= 0;
+#else
+  return false; // glibc < 2.9
+#endif
@@ -4162,4 +4135,4 @@
-  // If THPs are unconditionally enabled (THP mode "always") and MAP_STACK is not mapped to
-  // VM_NOHUGEPAGE in the kernel, khugepaged may attempt to coalesce small pages in thread stacks to
-  // huge pages. That costs a lot of memory and is usually unwanted for thread stacks. Therefore we
-  // attempt to prevent THP formation in thread stacks unless the user explicitly allowed THP
+  // If THPs are unconditionally enabled (THP mode "always") and the OS does not prevent THPs from
+  // being allocated for stack area, khugepaged may attempt to coalesce small pages in thread stacks
+  // to huge pages. That costs a lot of memory and is usually unwanted for thread stacks. Therefore
+  // we attempt to prevent THP formation in thread stacks unless the user explicitly allowed THP
@@ -4167,3 +4140,4 @@
-  if (HugePages::thp_mode() == THPMode::always && !kernel_maps_map_stack_to_nohugepage()) {
-    if (THPStackMitigation) {
-      log_info(pagesize)("JVM will attempt to prevent THPs in thread stacks.");
+  if (HugePages::thp_mode() == THPMode::always) {
+    if (os_prevents_thp_in_stack()) {
+      log_info(pagesize)("JVM does not need to prevent THPs in thread stacks on this OS.");
+      FLAG_SET_ERGO(THPStackMitigation, false); // Mitigation not needed
@@ -4171,1 +4145,5 @@
-      log_info(pagesize)("JVM will *not* prevent THPs in thread stacks. This may cause high RSS.");
+      if (THPStackMitigation) {
+        log_info(pagesize)("JVM will attempt to prevent THPs in thread stacks.");
+      } else {
+        log_info(pagesize)("JVM will *not* prevent THPs in thread stacks. This may cause high RSS.");
+      }
